 18px;\n  font-weight: 600;\n  line-height: 24px;\n  border: 1.5px solid #CBCBCB;\n  padding: 40px 40px 36px 48px;\n  flex-grow: 1;\n}\n\n.skd-web .profitably__item-subtitle {\n  margin-top: 0;\n  margin-bottom: 12px;\n  font-family: \"Manrope\";\n  font-weight: 600;\n  font-size: 18px;\n  line-height: 24px;\n}\n\n.skd-web .profitably__item-desc {\n  font-weight: 400;\n  font-size: 18px;\n}\n\n.skd-web .profitably__item-desc p {\n  margin: 0;\n}\n\n.skd-web .profitably__item-desc p:not(:last-child) {\n  margin-bottom: 8px;\n}\n\n.skd-web .profitably__item-desc--left img {\n  margin-right: 40px;\n  float: left;\n}\n\n.skd-web .profitably__item-desc img {\n  max-width: 206px;\n}\n\n.skd-web .profitably__item-desc-bottom {\n  margin-top: 16px;\n  position: relative;\n}\n\n.skd-web .profitably__item-desc--right img {\n  margin-left: 16px;\n  float: right;\n}\n\n.skd-web .profitably__users {\n  display: flex;\n  gap: 20px;\n}\n\n.skd-web .profitably__users-item {\n  border: 1.5px solid #CBCBCB;\n  padding: 40px;\n  width: 50%;\n}\n\n.skd-web .profitably__users-title {\n  display: flex;\n  align-items: flex-start;\n  gap: 16px;\n  margin: 0;\n  font-size: 20px;\n  line-height: 28px;\n}\n\n.skd-web .profitably__users-title span {\n  padding-top: 8px;\n}\n\n.skd-web .profitably__users-title p {\n  margin: 0;\n}\n\n.skd-web .profitably__users-subtitle {\n  margin: 0 0 4px 0;\n  color: #2c2d2e;\n  font-size: 16px;\n  font-weight: 600;\n  line-height: 20px;\n}\n\n.skd-web .profitably__users-list {\n  margin-top: 28px;\n  list-style-type: none;\n  counter-reset: num;\n  margin-left: 54px;\n  padding: 0;\n}\n\n.skd-web .profitably__users-list > li {\n  position: relative;\n  margin: 0;\n  padding: 8px 0 16px 0;\n}\n\n.skd-web .profitably__users-list > li::before {\n  content: \"0\" counter(num);\n  counter-increment: num;\n  display: inline-block;\n  position: absolute;\n  top: 6px;\n  left: -53px;\n  width: 38px;\n  text-align: center;\n  color: #6D7885;\n  font-size: 16px;\n  